<script>
    // Filter State logic
    let currentStatus = 'ALL';

    function setStatusFilter(status, btnElement) {
      currentStatus = status;
      document.querySelectorAll('.status-btn').forEach(btn => {
        btn.classList.remove('bg-primary-container', 'text-on-primary', 'shadow-[0_4px_12px_rgba(91,77,255,0.35)]');
        btn.classList.add('bg-surface-container-high', 'text-on-surface-variant');
      });
      btnElement.classList.remove('bg-surface-container-high', 'text-on-surface-variant');
      btnElement.classList.add('bg-primary-container', 'text-on-primary', 'shadow-[0_4px_12px_rgba(91,77,255,0.35)]');
      filterOrders();
    }

    function filterOrders() {
      const searchVal = document.getElementById('searchInput').value.toLowerCase();
      const cashierVal = document.getElementById('cashierFilter').value;
      const rows = document.querySelectorAll('.order-row');

      rows.forEach(row => {
        const id = row.getAttribute('data-id').toLowerCase();
        const cust = row.getAttribute('data-customer').toLowerCase();
        const cashier = row.getAttribute('data-cashier');
        const status = row.getAttribute('data-status');

        const matchesSearch = id.includes(searchVal) || cust.includes(searchVal) || cashier.toLowerCase().includes(searchVal);
        const matchesCashier = cashierVal === 'ALL' || cashier === cashierVal;
        const matchesStatus = currentStatus === 'ALL' || status === currentStatus;

        if (matchesSearch && matchesCashier && matchesStatus) {
          row.style.display = 'flex';
        } else {
          row.style.display = 'none';
        }
      });
    }

    function openModal(orderId) {
      const modal = document.getElementById('orderDetailModal');
      document.getElementById('modalOrderId').innerText = '#' + orderId;
      modal.classList.remove('hidden');
    }

    function closeModal() {
      const modal = document.getElementById('orderDetailModal');
      modal.classList.add('hidden');
    }

    // Close modal on escape key
    document.addEventListener('keydown', function(event) {
      if (event.key === 'Escape') {
        closeModal();
      }
    });
  </script>
